function DropdownMenu({ trigger, items }: DropdownMenuProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [highlighted, setHighlighted] = useState(-1);
  const rootRef = useRef<HTMLDivElement>(null);
  const triggerRef = useRef<HTMLButtonElement>(null);
  const typeaheadRef = useRef('');
  const typeaheadTimer = useRef<ReturnType<typeof setTimeout>>();

  const enabledIndexes = items
    .map((it, i) => (it.disabled ? -1 : i))
    .filter((i) => i !== -1);

  function open(initialIndex = enabledIndexes[0] ?? -1) {
    setIsOpen(true);
    setHighlighted(initialIndex);
  }
  function close() {
    setIsOpen(false);
    setHighlighted(-1);
    triggerRef.current?.focus();
  }

  useEffect(() => {
    if (!isOpen) return;
    function onClickOutside(e: MouseEvent) {
      if (rootRef.current && !rootRef.current.contains(e.target as Node)) close();
    }
    document.addEventListener('mousedown', onClickOutside);
    return () => document.removeEventListener('mousedown', onClickOutside);
  }, [isOpen]);

  function moveHighlight(delta: number) {
    if (enabledIndexes.length === 0) return;
    const pos = enabledIndexes.indexOf(highlighted);
    const next = pos === -1
      ? enabledIndexes[0]
      : enabledIndexes[(pos + delta + enabledIndexes.length) % enabledIndexes.length];
    setHighlighted(next);
  }

  function handleKeyDown(e: React.KeyboardEvent) {
    if (!isOpen) {
      if (['Enter', ' ', 'ArrowDown'].includes(e.key)) { e.preventDefault(); open(); }
      return;
    }
    switch (e.key) {
      case 'ArrowDown': e.preventDefault(); moveHighlight(1); break;
      case 'ArrowUp': e.preventDefault(); moveHighlight(-1); break;
      case 'Home': e.preventDefault(); setHighlighted(enabledIndexes[0]); break;
      case 'End': e.preventDefault(); setHighlighted(enabledIndexes[enabledIndexes.length - 1]); break;
      case 'Escape': e.preventDefault(); close(); break;
      case 'Enter':
      case ' ':
        e.preventDefault();
        if (highlighted !== -1) { items[highlighted].onSelect(); close(); }
        break;
      default:
        if (e.key.length === 1) {
          clearTimeout(typeaheadRef.current ? undefined : undefined);
          typeaheadRef.current += e.key.toLowerCase();
          const match = items.findIndex(
            (it, i) => !it.disabled && it.label.toLowerCase().startsWith(typeaheadRef.current)
          );
          if (match !== -1) setHighlighted(match);
          clearTimeout(typeaheadTimer.current);
          typeaheadTimer.current = setTimeout(() => (typeaheadRef.current = ''), 500);
        }
    }
  }

  return (
    <div ref={rootRef} className="relative inline-block" onKeyDown={handleKeyDown}>
      <button
        ref={triggerRef}
        aria-haspopup="menu"
        aria-expanded={isOpen}
        onClick={() => (isOpen ? close() : open())}
      >
        {trigger}
      </button>
      {isOpen && (
        <ul role="menu" className="absolute right-0 mt-1 w-48 rounded-md border bg-white py-1 shadow-lg">
          {items.map((item, i) => (
            <li
              key={item.id}
              role="menuitem"
              aria-disabled={item.disabled}
              className={
                'cursor-pointer px-3 py-2 text-sm ' +
                (i === highlighted ? 'bg-slate-100 ' : '') +
                (item.disabled ? 'cursor-not-allowed text-slate-400' : item.destructive ? 'text-red-600' : 'text-slate-900')
              }
              onMouseEnter={() => !item.disabled && setHighlighted(i)}
              onClick={() => { if (!item.disabled) { item.onSelect(); close(); } }}
            >
              {item.label}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

