interface TabsProps {
  defaultTab?: string;
  activeTab?: string;
  onChange?: (id: string) => void;
  children: React.ReactNode;
}
interface TabItem { id: string; label: string; disabled?: boolean; }

referenceSolution:
const TabsContext = createContext<{
  activeId: string;
  setActiveId: (id: string) => void;
} | null>(null);

function Tabs({ defaultTab, activeTab, onChange, children }: TabsProps) {
  const [internal, setInternal] = useState(defaultTab ?? '');
  const isControlled = activeTab !== undefined;
  const activeId = isControlled ? activeTab! : internal;
  const setActiveId = (id: string) => {
    if (!isControlled) setInternal(id);
    onChange?.(id);
  };
  return (
    <TabsContext.Provider value={{ activeId, setActiveId }}>
      <div>{children}</div>
    </TabsContext.Provider>
  );
}

function TabList({ tabs }: { tabs: TabItem[] }) {
  const ctx = useContext(TabsContext)!;
  const enabled = tabs.filter((t) => !t.disabled).map((t) => t.id);

  function onKeyDown(e: React.KeyboardEvent) {
    const pos = enabled.indexOf(ctx.activeId);
    if (pos === -1) return;
    if (e.key === 'ArrowRight') {
      e.preventDefault();
      ctx.setActiveId(enabled[(pos + 1) % enabled.length]);
    } else if (e.key === 'ArrowLeft') {
      e.preventDefault();
      ctx.setActiveId(enabled[(pos - 1 + enabled.length) % enabled.length]);
    } else if (e.key === 'Home') {
      e.preventDefault();
      ctx.setActiveId(enabled[0]);
    } else if (e.key === 'End') {
      e.preventDefault();
      ctx.setActiveId(enabled[enabled.length - 1]);
    }
  }

  return (
    <div role="tablist" onKeyDown={onKeyDown} className="flex border-b">
      {tabs.map((tab) => (
        <button
          key={tab.id}
          role="tab"
          id={'tab-' + tab.id}
          aria-selected={ctx.activeId === tab.id}
          aria-controls={'panel-' + tab.id}
          aria-disabled={tab.disabled}
          tabIndex={ctx.activeId === tab.id ? 0 : -1}
          disabled={tab.disabled}
          onClick={() => ctx.setActiveId(tab.id)}
          className={'px-4 py-2 text-sm ' + (ctx.activeId === tab.id ? 'border-b-2 border-slate-900 font-medium' : 'text-slate-500')}
        >
          {tab.label}
        </button>
      ))}
    </div>
  );
}

function TabPanel({ id, children }: { id: string; children: React.ReactNode }) {
  const ctx = useContext(TabsContext)!;
  if (ctx.activeId !== id) return null;
  return (
    <div role="tabpanel" id={'panel-' + id} aria-labelledby={'tab-' + id} tabIndex={0}>
      {children}
    </div>
  );
}

