interface AccordionItemData { id: string; header: string; content: React.ReactNode; }
interface AccordionProps {
  mode: 'single' | 'multiple';
  items: AccordionItemData[];
  defaultExpandedIds?: string[];
  expandedIds?: string[];
  onChange?: (ids: string[]) => void;
}

referenceSolution:
// CSS-driven height animation avoids JS measuring entirely:
// .panel-wrapper { display: grid; grid-template-rows: 0fr; transition: grid-template-rows 200ms ease; }
// .panel-wrapper[data-expanded="true"] { grid-template-rows: 1fr; }
// .panel-inner { overflow: hidden; min-height: 0; }
// @media (prefers-reduced-motion: reduce) { .panel-wrapper { transition: none; } }

function Accordion({ mode, items, defaultExpandedIds, expandedIds, onChange }: AccordionProps) {
  const [internal, setInternal] = useState<string[]>(defaultExpandedIds ?? []);
  const isControlled = expandedIds !== undefined;
  const expanded = isControlled ? expandedIds! : internal;

  function toggle(id: string) {
    let next: string[];
    if (mode === 'single') {
      next = expanded.includes(id) ? [] : [id];
    } else {
      next = expanded.includes(id) ? expanded.filter((x) => x !== id) : [...expanded, id];
    }
    if (!isControlled) setInternal(next);
    onChange?.(next);
  }

  const headerIds = items.map((it) => 'header-' + it.id);

  function onHeaderKeyDown(e: React.KeyboardEvent, index: number) {
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault();
      const dir = e.key === 'ArrowDown' ? 1 : -1;
      const nextIndex = (index + dir + items.length) % items.length;
      document.getElementById(headerIds[nextIndex])?.focus();
    }
    if (e.key === 'Home') document.getElementById(headerIds[0])?.focus();
    if (e.key === 'End') document.getElementById(headerIds[headerIds.length - 1])?.focus();
  }

  return (
    <div>
      {items.map((item, i) => {
        const isOpen = expanded.includes(item.id);
        return (
          <div key={item.id} className="border-b">
            <h3>
              <button
                id={headerIds[i]}
                aria-expanded={isOpen}
                aria-controls={'panel-' + item.id}
                onClick={() => toggle(item.id)}
                onKeyDown={(e) => onHeaderKeyDown(e, i)}
                className="flex w-full items-center justify-between py-3 text-left font-medium"
              >
                {item.header}
                <ChevronIcon className={isOpen ? 'rotate-180 transition-transform' : 'transition-transform'} />
              </button>
            </h3>
            <div
              id={'panel-' + item.id}
              role="region"
              aria-labelledby={headerIds[i]}
              data-expanded={isOpen}
              className="grid transition-[grid-template-rows] duration-200 ease-in-out"
              style={{ gridTemplateRows: isOpen ? '1fr' : '0fr' }}
            >
              <div className="overflow-hidden min-h-0">
                <div className="pb-4">{item.content}</div>
              </div>
            </div>
          </div>
        );
      })}
    </div>
  );
}

