type ToastType = 'success' | 'error' | 'warning' | 'info';
interface ToastItem {
  id: string;
  type: ToastType;
  message: string;
  duration: number;
  createdAt: number;
}
// usage anywhere:
toast.success('Invoice #1042 saved');
toast.error('Payment failed -- please retry');

referenceSolution:
// toastStore.ts
type Listener = () => void;
let toasts: ToastItem[] = [];
const listeners = new Set<Listener>();

function notify() { listeners.forEach((l) => l()); }

export const toastStore = {
  subscribe(listener: Listener) {
    listeners.add(listener);
    return () => listeners.delete(listener);
  },
  getSnapshot() { return toasts; },
  push(type: ToastType, message: string, duration = 4000) {
    const id = crypto.randomUUID();
    toasts = [...toasts, { id, type, message, duration, createdAt: Date.now() }];
    notify();
    return id;
  },
  dismiss(id: string) {
    toasts = toasts.filter((t) => t.id !== id);
    notify();
  },
};

export const toast = {
  success: (msg: string, duration?: number) => toastStore.push('success', msg, duration),
  error: (msg: string, duration?: number) => toastStore.push('error', msg, duration),
  warning: (msg: string, duration?: number) => toastStore.push('warning', msg, duration),
  info: (msg: string, duration?: number) => toastStore.push('info', msg, duration),
  dismiss: (id: string) => toastStore.dismiss(id),
};

// ToastProvider.tsx
function ToastProvider() {
  const toasts = useSyncExternalStore(toastStore.subscribe, toastStore.getSnapshot, () => []);
  const visible = toasts.slice(-5);
  const overflow = toasts.length - visible.length;

  return createPortal(
    <div aria-live="polite" className="fixed bottom-4 right-4 z-[100] flex flex-col gap-2">
      {overflow > 0 && <div className="text-xs text-slate-500">+{overflow} more</div>}
      {visible.map((t) => (
        <ToastCard key={t.id} toast={t} />
      ))}
    </div>,
    document.body
  );
}

function ToastCard({ toast: t }: { toast: ToastItem }) {
  const remaining = useRef(t.duration);
  const timerStart = useRef(Date.now());
  const timeoutId = useRef<ReturnType<typeof setTimeout>>();

  function startTimer() {
    timerStart.current = Date.now();
    timeoutId.current = setTimeout(() => toastStore.dismiss(t.id), remaining.current);
  }
  function pauseTimer() {
    clearTimeout(timeoutId.current);
    remaining.current -= Date.now() - timerStart.current;
  }

  useEffect(() => {
    startTimer();
    return () => clearTimeout(timeoutId.current);
  }, []);

  return (
    <div
      role={t.type === 'error' ? 'alert' : 'status'}
      onMouseEnter={pauseTimer}
      onMouseLeave={startTimer}
      onFocus={pauseTimer}
      onBlur={startTimer}
      className={'flex items-start gap-2 rounded-md border p-3 shadow-md ' + toastColors[t.type]}
    >
      <ToastIcon type={t.type} />
      <p className="flex-1 text-sm">{t.message}</p>
      <button aria-label="Dismiss notification" onClick={() => toastStore.dismiss(t.id)}>
        <XIcon className="h-4 w-4" />
      </button>
    </div>
  );
}

