referenceSolution:
function useDebouncedValue<T>(value: T, delay: number): T {
  const [debounced, setDebounced] = useState(value);
  useEffect(() => {
    const id = setTimeout(() => setDebounced(value), delay);
    return () => clearTimeout(id);
  }, [value, delay]);
  return debounced;
}

function SearchInput({ onSearchChange, delay = 350 }: { onSearchChange: (q: string) => void; delay?: number }) {
  const [rawValue, setRawValue] = useState('');
  const debouncedValue = useDebouncedValue(rawValue, delay);
  const requestId = useRef(0);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    if (debouncedValue === '') {
      setIsLoading(false);
      onSearchChange('');
      return;
    }
    const myId = ++requestId.current;
    setIsLoading(true);
    fetchResults(debouncedValue).then((results) => {
      if (myId !== requestId.current) return; // stale response, ignore
      setIsLoading(false);
      onSearchChange(debouncedValue);
    });
  }, [debouncedValue]);

  function handleClear() {
    requestId.current++; // invalidate any in-flight request
    setRawValue('');
    setIsLoading(false);
    onSearchChange('');
  }

  return (
    <div className="relative w-full max-w-sm">
      <label htmlFor="catalog-search" className="sr-only">Search products</label>
      <input
        id="catalog-search"
        value={rawValue}
        onChange={(e) => setRawValue(e.target.value)}
        placeholder="Search products..."
        className="w-full rounded-md border px-3 py-2 pr-16 text-sm"
        aria-busy={isLoading}
      />
      {isLoading && <Spinner className="absolute right-8 top-2.5 h-4 w-4" />}
      {rawValue && (
        <button aria-label="Clear search" onClick={handleClear} className="absolute right-2 top-2.5">
          <XIcon className="h-4 w-4" />
        </button>
      )}
    </div>
  );
}

