interface Customer { id: string; name: string; email: string; }
interface AutocompleteProps {
  onSelect: (customer: Customer) => void;
  fetchSuggestions: (query: string) => Promise<Customer[]>;
}

referenceSolution:
function Autocomplete({ onSelect, fetchSuggestions }: AutocompleteProps) {
  const [query, setQuery] = useState('');
  const [isOpen, setIsOpen] = useState(false);
  const [highlighted, setHighlighted] = useState(-1);
  const debounced = useDebouncedValue(query, 300);

  const { data: suggestions = [], isLoading, isError, refetch } = useQuery({
    queryKey: ['customer-suggestions', debounced],
    queryFn: () => fetchSuggestions(debounced),
    enabled: debounced.length > 0 && isOpen,
  });

  function handleChange(e: React.ChangeEvent<HTMLInputElement>) {
    setQuery(e.target.value);
    setIsOpen(true);
    setHighlighted(-1);
  }

  function commit(customer: Customer) {
    setQuery(customer.name);
    setIsOpen(false);
    onSelect(customer);
  }

  function onKeyDown(e: React.KeyboardEvent) {
    if (!isOpen && e.key === 'ArrowDown') { setIsOpen(true); return; }
    if (!isOpen) return;
    if (e.key === 'ArrowDown') {
      e.preventDefault();
      setHighlighted((i) => Math.min(i + 1, suggestions.length - 1));
    } else if (e.key === 'ArrowUp') {
      e.preventDefault();
      setHighlighted((i) => Math.max(i - 1, 0));
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (highlighted !== -1 && suggestions[highlighted]) commit(suggestions[highlighted]);
    } else if (e.key === 'Escape') {
      setIsOpen(false);
      setHighlighted(-1);
    }
  }

  const activeId = highlighted !== -1 ? 'option-' + suggestions[highlighted]?.id : undefined;

  return (
    <div className="relative w-full max-w-sm">
      <input
        role="combobox"
        aria-autocomplete="list"
        aria-expanded={isOpen}
        aria-controls="customer-listbox"
        aria-activedescendant={activeId}
        value={query}
        onChange={handleChange}
        onKeyDown={onKeyDown}
        onBlur={() => setTimeout(() => setIsOpen(false), 100)}
        className="w-full rounded-md border px-3 py-2 text-sm"
      />
      {isOpen && (
        <ul id="customer-listbox" role="listbox" className="absolute z-10 mt-1 max-h-60 w-full overflow-auto rounded-md border bg-white shadow-lg">
          {isLoading && <li className="px-3 py-2 text-sm text-slate-400">Searching...</li>}
          {isError && (
            <li className="px-3 py-2 text-sm text-red-600">
              Something went wrong. <button onClick={() => refetch()} className="underline">Retry</button>
            </li>
          )}
          {!isLoading && !isError && suggestions.length === 0 && debounced && (
            <li className="px-3 py-2 text-sm text-slate-400">No customers found</li>
          )}
          {suggestions.map((c, i) => (
            <li
              key={c.id}
              id={'option-' + c.id}
              role="option"
              aria-selected={i === highlighted}
              onMouseDown={() => commit(c)}
              onMouseEnter={() => setHighlighted(i)}
              className={'cursor-pointer px-3 py-2 text-sm ' + (i === highlighted ? 'bg-slate-100' : '')}
            >
              <HighlightMatch text={c.name} query={debounced} />
              <span className="ml-2 text-xs text-slate-400">{c.email}</span>
            </li>
          ))}
        </ul>
      )}
      <span className="sr-only" aria-live="polite">
        {!isLoading && suggestions.length > 0 ? suggestions.length + ' results available' : ''}
      </span>
    </div>
  );
}

function HighlightMatch({ text, query }: { text: string; query: string }) {
  if (!query) return <>{text}</>;
  const idx = text.toLowerCase().indexOf(query.toLowerCase());
  if (idx === -1) return <>{text}</>;
  return (
    <>
      {text.slice(0, idx)}
      <strong>{text.slice(idx, idx + query.length)}</strong>
      {text.slice(idx + query.length)}
    </>
  );
}

