// useTableState.ts -- URL is the single source of truth
function useTableState(defaultPageSize = 25): [TableState, (patch: Partial<TableState>) => void] {
  const [params, setParams] = useSearchParams();

  const state: TableState = {
    search: params.get('search') ?? '',
    filters: JSON.parse(params.get('filters') ?? '{}'),
    sort: params.get('sort')
      ? { columnKey: params.get('sort')!.split(':')[0], direction: params.get('sort')!.split(':')[1] as 'asc' | 'desc' }
      : null,
    page: Number(params.get('page') ?? '1'),
    pageSize: Number(params.get('pageSize') ?? String(defaultPageSize)),
  };

  function update(patch: Partial<TableState>) {
    const next = { ...state, ...patch };
    // Any change other than an explicit page change resets to page 1
    if (!('page' in patch)) next.page = 1;
    const nextParams = new URLSearchParams();
    if (next.search) nextParams.set('search', next.search);
    if (Object.keys(next.filters).length) nextParams.set('filters', JSON.stringify(next.filters));
    if (next.sort) nextParams.set('sort', next.sort.columnKey + ':' + next.sort.direction);
    nextParams.set('page', String(next.page));
    nextParams.set('pageSize', String(next.pageSize));
    setParams(nextParams, { replace: true });
  }

  return [state, update];
}

// Client-side pipeline -- filter -> search -> sort -> paginate
function useClientPipeline<T>(data: T[], columns: Column<T>[], state: TableState) {
  return useMemo(() => {
    let rows = data;

    Object.entries(state.filters).forEach(([key, value]) => {
      if (!value || (Array.isArray(value) && value.length === 0)) return;
      rows = rows.filter((row) => {
        const rowValue = (row as any)[key];
        return Array.isArray(value) ? value.includes(rowValue) : rowValue === value;
      });
    });

    if (state.search) {
      const q = state.search.toLowerCase();
      const searchableCols = columns.filter((c) => c.sortValue); // reuse sortValue as the "raw text" source
      rows = rows.filter((row) =>
        searchableCols.some((c) => String(c.sortValue!(row) ?? '').toLowerCase().includes(q))
      );
    }

    if (state.sort) {
      const col = columns.find((c) => c.key === state.sort!.columnKey);
      if (col?.sortValue) {
        const dir = state.sort.direction === 'asc' ? 1 : -1;
        rows = [...rows].sort((a, b) => {
          const av = col.sortValue!(a);
          const bv = col.sortValue!(b);
          if (av == null) return 1;
          if (bv == null) return -1;
          if (av < bv) return -1 * dir;
          if (av > bv) return 1 * dir;
          return 0;
        });
      }
    }

    const total = rows.length;
    const start = (state.page - 1) * state.pageSize;
    const pageRows = rows.slice(start, start + state.pageSize);
    return { rows: pageRows, total };
  }, [data, columns, state]);
}

// DataTableHeader.tsx -- sort cycling + tri-state select-all
function SortableHeaderCell<T>({ column, state, onStateChange }: { column: Column<T>; state: TableState; onStateChange: (p: Partial<TableState>) => void }) {
  const isActive = state.sort?.columnKey === column.key;
  const direction = isActive ? state.sort!.direction : undefined;

  function cycleSort() {
    if (!isActive) return onStateChange({ sort: { columnKey: column.key, direction: 'asc' } });
    if (direction === 'asc') return onStateChange({ sort: { columnKey: column.key, direction: 'desc' } });
    return onStateChange({ sort: null });
  }

  return (
    <th
      scope="col"
      aria-sort={isActive ? (direction === 'asc' ? 'ascending' : 'descending') : 'none'}
      style={{ width: column.width }}
    >
      {column.sortable ? (
        <button onClick={cycleSort} className="flex items-center gap-1 font-medium">
          {column.header}
          <SortIcon direction={direction} />
        </button>
      ) : (
        column.header
      )}
    </th>
  );
}

function SelectAllCheckbox({ pageRowIds, selectedIds, onSelectionChange }: {
  pageRowIds: string[];
  selectedIds: Set<string>;
  onSelectionChange: (ids: Set<string>) => void;
}) {
  const ref = useRef<HTMLInputElement>(null);
  const selectedOnPage = pageRowIds.filter((id) => selectedIds.has(id));
  const allSelected = pageRowIds.length > 0 && selectedOnPage.length === pageRowIds.length;
  const someSelected = selectedOnPage.length > 0 && !allSelected;

  useEffect(() => {
    if (ref.current) ref.current.indeterminate = someSelected;
  }, [someSelected]);

  function toggleAll() {
    const next = new Set(selectedIds);
    if (allSelected) pageRowIds.forEach((id) => next.delete(id));
    else pageRowIds.forEach((id) => next.add(id));
    onSelectionChange(next);
  }

  return (
    <input
      ref={ref}
      type="checkbox"
      checked={allSelected}
      onChange={toggleAll}
      aria-label="Select all orders on this page"
    />
  );
}

// Responsive: same data, two render paths chosen by a media-query hook
function DataTableBody<T>({ rows, columns, getRowId, selectedIds, onSelectionChange }: any) {
  const isMobile = useMediaQuery('(max-width: 640px)');
  if (isMobile) {
    return (
      <div className="flex flex-col gap-3">
        {rows.map((row: T) => (
          <div key={getRowId(row)} className="rounded-md border p-3">
            {columns.map((col: Column<T>) => (
              <div key={col.key} className="flex justify-between py-1 text-sm">
                <span className="text-slate-500">{col.header}</span>
                <span>{col.accessor(row)}</span>
              </div>
            ))}
          </div>
        ))}
      </div>
    );
  }
  return (
    <tbody>
      {rows.map((row: T) => {
        const id = getRowId(row);
        return (
          <tr key={id} className={selectedIds.has(id) ? 'bg-slate-50' : ''}>
            <td>
              <input
                type="checkbox"
                checked={selectedIds.has(id)}
                onChange={() => {
                  const next = new Set(selectedIds);
                  next.has(id) ? next.delete(id) : next.add(id);
                  onSelectionChange(next);
                }}
                aria-label={'Select row ' + id}
              />
            </td>
            {columns.map((col: Column<T>) => (
              <td key={col.key} style={{ textAlign: col.align ?? 'left' }}>
                {col.accessor(row)}
              </td>
            ))}
          </tr>
        );
      })}
    </tbody>
  );
}

// SERVER-SIDE MODE NOTES (discussed live, not fully coded):
// - onStateChange(state) serializes TableState into query params sent via useQuery({ queryKey: ['orders', state], queryFn: () => api.getOrders(state) })
// - Server returns { rows, total } already filtered/sorted/paginated -- client pipeline (useClientPipeline) is skipped entirely in this mode
// - Server MUST independently enforce filter scope (e.g. a support agent's role restricts which statuses/customers they can query) -- client-sent filters are a UX convenience only, never trusted as an authorization boundary
// - For 50k+ rows that must stay client-side (rare, e.g. an offline-capable tool), reach for @tanstack/react-virtual to window-render only visible rows rather than paginate; for server-backed admin tables, pagination is almost always preferred over virtualization since it also bounds payload size and query cost, not just DOM node count

