interface PaginationProps {
  totalItems: number;
  pageSize: number;
  currentPage: number;
  onPageChange: (page: number) => void;
  siblingCount?: number; // how many page numbers to show beside the current page
}

referenceSolution:
function usePaginationRange(currentPage: number, totalPages: number, siblingCount = 1): (number | 'ellipsis')[] {
  const totalSlots = siblingCount * 2 + 5; // first, last, current, 2 ellipses
  if (totalPages <= totalSlots) {
    return Array.from({ length: totalPages }, (_, i) => i + 1);
  }
  const leftSibling = Math.max(currentPage - siblingCount, 1);
  const rightSibling = Math.min(currentPage + siblingCount, totalPages);
  const showLeftEllipsis = leftSibling > 2;
  const showRightEllipsis = rightSibling < totalPages - 1;

  const range: (number | 'ellipsis')[] = [1];
  if (showLeftEllipsis) range.push('ellipsis');
  for (let p = leftSibling; p <= rightSibling; p++) {
    if (p !== 1 && p !== totalPages) range.push(p);
  }
  if (showRightEllipsis) range.push('ellipsis');
  range.push(totalPages);
  return range;
}

function Pagination({ totalItems, pageSize, currentPage, onPageChange, siblingCount = 1 }: PaginationProps) {
  const totalPages = Math.max(1, Math.ceil(totalItems / pageSize));
  const safePage = Math.min(Math.max(currentPage, 1), totalPages);
  const pages = usePaginationRange(safePage, totalPages, siblingCount);

  if (totalPages <= 1) return null;

  return (
    <nav aria-label="Pagination" className="flex items-center gap-1">
      <button
        aria-label="Previous page"
        disabled={safePage === 1}
        onClick={() => onPageChange(safePage - 1)}
      >
        Prev
      </button>
      {pages.map((p, i) =>
        p === 'ellipsis' ? (
          <span key={'e' + i} aria-hidden="true" className="px-2">...</span>
        ) : (
          <button
            key={p}
            aria-current={p === safePage ? 'page' : undefined}
            onClick={() => onPageChange(p)}
            className={p === safePage ? 'bg-slate-900 text-white' : ''}
          >
            {p}
          </button>
        )
      )}
      <button
        aria-label="Next page"
        disabled={safePage === totalPages}
        onClick={() => onPageChange(safePage + 1)}
      >
        Next
      </button>
    </nav>
  );
}

