interface Listing {
  id: string;
  title: string;
  description: string;
  category: string;
  price: number;
  status: 'active' | 'draft' | 'archived';
  createdAt: string;
  popularityScore: number;
}
interface FilterState {
  search: string;
  categories: string[];
  priceRange: { min: number | null; max: number | null };
  status: 'all' | 'active' | 'draft' | 'archived';
  sort: 'newest' | 'price-asc' | 'price-desc' | 'popularity';
}

referenceSolution:
function useFilteredListings(listings: Listing[], filters: FilterState) {
  return useMemo(() => {
    let result = listings;

    if (filters.status !== 'all') {
      result = result.filter((l) => l.status === filters.status);
    }

    if (filters.categories.length > 0) {
      result = result.filter((l) => filters.categories.includes(l.category));
    }

    const { min, max } = filters.priceRange;
    if (min != null) result = result.filter((l) => l.price >= min);
    if (max != null) result = result.filter((l) => l.price <= max);

    if (filters.search.trim()) {
      const q = filters.search.trim().toLowerCase();
      result = result.filter(
        (l) => l.title.toLowerCase().includes(q) || l.description.toLowerCase().includes(q)
      );
    }

    const sorted = [...result].sort((a, b) => {
      switch (filters.sort) {
        case 'newest':
          return new Date(b.createdAt).getTime() - new Date(a.createdAt).getTime();
        case 'price-asc':
          return a.price - b.price;
        case 'price-desc':
          return b.price - a.price;
        case 'popularity':
          return b.popularityScore - a.popularityScore;
        default:
          return 0;
      }
    });

    return sorted;
  }, [listings, filters]);
}

function ResultsSummaryBar({ filters, resultsCount, onClearAll }: {
  filters: FilterState;
  resultsCount: number;
  onClearAll: () => void;
}) {
  const hasActiveFilters =
    filters.search !== '' ||
    filters.categories.length > 0 ||
    filters.priceRange.min != null ||
    filters.priceRange.max != null ||
    filters.status !== 'all';

  return (
    <div className="flex items-center justify-between py-2 text-sm">
      <span aria-live="polite">{resultsCount} results</span>
      {hasActiveFilters && (
        <button onClick={onClearAll} className="text-slate-500 underline">
          Clear all filters
        </button>
      )}
    </div>
  );
}

