function MerchantOnboardingWizard() {
  const methods = useForm<MerchantOnboardingForm>({
    resolver: zodResolver(merchantSchema),
    defaultValues: loadDraft() ?? defaultValues,
    mode: 'onBlur',
  });
  const [stepIndex, setStepIndex] = useState(0);
  const [completedSteps, setCompletedSteps] = useState<Set<number>>(new Set());

  useEffect(() => {
    const subscription = methods.watch((values) => saveDraftDebounced(values));
    return () => subscription.unsubscribe();
  }, [methods]);

  async function next() {
    const valid = await methods.trigger(stepFields[stepIndex]);
    if (!valid) return;
    setCompletedSteps((prev) => new Set(prev).add(stepIndex));
    setStepIndex((i) => Math.min(i + 1, steps.length - 1));
  }

  function back() {
    setStepIndex((i) => Math.max(i - 1, 0));
  }

  function goToStep(target: number) {
    if (target <= stepIndex || completedSteps.has(target)) setStepIndex(target);
  }

  async function onSubmit(data: MerchantOnboardingForm) {
    try {
      await api.submitMerchantOnboarding(data);
      clearDraft();
    } catch (err) {
      // Surface a submit-level error; keep the draft intact for retry
      methods.setError('root', { message: 'Submission failed -- please try again.' });
    }
  }

  return (
    <FormProvider {...methods}>
      <StepIndicator current={stepIndex} completed={completedSteps} onStepClick={goToStep} />
      <form onSubmit={methods.handleSubmit(onSubmit)}>
        {stepIndex === 0 && <BusinessInfoStep />}
        {stepIndex === 1 && <ContactDetailsStep />}
        {stepIndex === 2 && <BankAccountStep />}
        {stepIndex === 3 && <ReviewStep onEditStep={goToStep} />}

        <div className="mt-6 flex justify-between">
          <button type="button" onClick={back} disabled={stepIndex === 0}>Back</button>
          {stepIndex < 3 ? (
            <button type="button" onClick={next}>Continue</button>
          ) : (
            <button type="submit">Submit application</button>
          )}
        </div>
      </form>
    </FormProvider>
  );
}

