const checkoutSchema = z.object({
  fullName: z.string().min(1, 'Name is required'),
  email: z.string().email('Enter a valid email'),
  cardNumber: z.string().refine(isValidLuhn, 'Invalid card number'),
  expiry: z.string().regex(/^(0[1-9]|1[0-2])\/[0-9]{2}$/, 'Use MM/YY'),
  cvc: z.string().min(3).max(4),
  country: z.enum(['US', 'GB', 'IN']),
  postalCode: z.string(),
}).superRefine((data, ctx) => {
  const patterns: Record<string, RegExp> = {
    US: /^[0-9]{5}$/,
    GB: /^[A-Z]{1,2}[0-9][A-Z0-9]? ?[0-9][A-Z]{2}$/i,
    IN: /^[0-9]{6}$/,
  };
  if (!patterns[data.country].test(data.postalCode)) {
    ctx.addIssue({ code: 'custom', path: ['postalCode'], message: 'Invalid postal code for selected country' });
  }
});

