type CheckoutFormValues = z.infer<typeof checkoutSchema>;

function CheckoutForm() {
  const {
    register, handleSubmit, control, watch, setError,
    formState: { errors, isSubmitting },
  } = useForm<CheckoutFormValues>({
    resolver: zodResolver(checkoutSchema),
    mode: 'onBlur',
    reValidateMode: 'onChange',
    defaultValues: { country: 'US' },
  });

  const submitCheckout = useSubmitCheckout();

  async function onSubmit(values: CheckoutFormValues) {
    try {
      await submitCheckout.mutateAsync(values);
    } catch (err: any) {
      if (err.field && err.field in checkoutSchema.shape) {
        setError(err.field as keyof CheckoutFormValues, { message: err.message });
      } else {
        setError('root', { message: err.message ?? 'Payment could not be processed. Please try again.' });
      }
    }
  }

  return (
    <form onSubmit={handleSubmit(onSubmit)} noValidate>
      {errors.root && <p role="alert" className="mb-4 rounded bg-red-50 p-3 text-sm text-red-700">{errors.root.message}</p>}

      <FormField label="Full name" error={errors.fullName?.message}>
        <input {...register('fullName')} aria-invalid={!!errors.fullName} />
      </FormField>

      <FormField label="Email" error={errors.email?.message}>
        <input type="email" {...register('email')} aria-invalid={!!errors.email} />
      </FormField>

      <Controller
        name="cardNumber"
        control={control}
        render={({ field }) => (
          <FormField label="Card number" error={errors.cardNumber?.message}>
            <input
              value={formatCardNumber(field.value ?? '')}
              onChange={(e) => field.onChange(e.target.value.replace(/\s/g, ''))}
              onBlur={field.onBlur}
              inputMode="numeric"
              aria-invalid={!!errors.cardNumber}
            />
          </FormField>
        )}
      />

      <FormField label="Country" error={errors.country?.message}>
        <select {...register('country')}>
          <option value="US">United States</option>
          <option value="GB">United Kingdom</option>
          <option value="IN">India</option>
        </select>
      </FormField>

      <FormField label="Postal code" error={errors.postalCode?.message}>
        <input {...register('postalCode')} aria-invalid={!!errors.postalCode} />
      </FormField>

      <button type="submit" disabled={isSubmitting} aria-busy={isSubmitting}>
        {isSubmitting ? 'Processing...' : 'Pay now'}
      </button>
    </form>
  );
}

function formatCardNumber(raw: string) {
  return raw.replace(/\D/g, '').replace(/(.{4})/g, '$1 ').trim();
}

function isValidLuhn(cardNumber: string) {
  const digits = cardNumber.replace(/\s/g, '');
  let sum = 0;
  let shouldDouble = false;
  for (let i = digits.length - 1; i >= 0; i--) {
    let digit = parseInt(digits[i], 10);
    if (shouldDouble) {
      digit *= 2;
      if (digit > 9) digit -= 9;
    }
    sum += digit;
    shouldDouble = !shouldDouble;
  }
  return digits.length >= 13 && sum % 10 === 0;
}

