function useIntersectionObserver(ref: React.RefObject<Element>, options?: IntersectionObserverInit) {
  const [isIntersecting, setIsIntersecting] = useState(false);
  useEffect(() => {
    const node = ref.current;
    if (!node) return;
    const observer = new IntersectionObserver(([entry]) => {
      setIsIntersecting(entry.isIntersecting);
    }, { rootMargin: '200px', ...options });
    observer.observe(node);
    return () => observer.disconnect();
  }, [ref, options]);
  return isIntersecting;
}

function ActivityFeed() {
  const sentinelRef = useRef<HTMLDivElement>(null);
  const isSentinelVisible = useIntersectionObserver(sentinelRef);

  const {
    data, fetchNextPage, hasNextPage, isFetchingNextPage, isError, refetch,
  } = useInfiniteQuery({
    queryKey: ['activity-feed'],
    queryFn: ({ pageParam }) => fetchActivityPage(pageParam),
    initialPageParam: null as string | null,
    getNextPageParam: (lastPage: Page) => lastPage.nextCursor,
  });

  useEffect(() => {
    if (isSentinelVisible && hasNextPage && !isFetchingNextPage && !isError) {
      fetchNextPage();
    }
  }, [isSentinelVisible, hasNextPage, isFetchingNextPage, isError, fetchNextPage]);

  const items = data?.pages.flatMap((p) => p.items) ?? [];

  return (
    <div>
      <ul>
        {items.map((item) => (
          <li key={item.id} className="border-b py-3">
            <p>{item.message}</p>
            <time className="text-xs text-slate-400">{item.createdAt}</time>
          </li>
        ))}
      </ul>

      <div ref={sentinelRef} aria-hidden={!hasNextPage} className="h-1" />

      {isFetchingNextPage && (
        <p role="status" aria-label="Loading more items" className="py-4 text-center text-sm text-slate-400">
          Loading more...
        </p>
      )}

      {isError && (
        <div className="py-4 text-center">
          <p className="text-sm text-red-600">Failed to load more items.</p>
          <button onClick={() => fetchNextPage()} className="mt-2 underline">Retry</button>
        </div>
      )}

      {!hasNextPage && items.length > 0 && (
