interface UploadEntry {
  id: string;
  file: File;
  status: 'queued' | 'uploading' | 'success' | 'error' | 'cancelled';
  progress: number; // 0-100
  error?: string;
}
const MAX_FILE_SIZE = 10 * 1024 * 1024; // 10MB
const ALLOWED_TYPES = ['application/pdf', 'image/png', 'image/jpeg'];

referenceSolution:
function validateFile(file: File): string | null {
  if (file.size > MAX_FILE_SIZE) return 'File exceeds 10MB limit';
  if (!ALLOWED_TYPES.includes(file.type)) return 'Only PDF, PNG, and JPG files are allowed';
  return null;
}

function uploadWithProgress(
  file: File,
  onProgress: (pct: number) => void,
  signal: AbortSignal
): Promise<void> {
  return new Promise((resolve, reject) => {
    const xhr = new XMLHttpRequest();
    xhr.open('POST', '/api/uploads');

    xhr.upload.onprogress = (e) => {
      if (e.lengthComputable) onProgress(Math.round((e.loaded / e.total) * 100));
    };
    xhr.onload = () => (xhr.status >= 200 && xhr.status < 300 ? resolve() : reject(new Error('Upload failed')));
    xhr.onerror = () => reject(new Error('Network error'));
    xhr.onabort = () => reject(new DOMException('Aborted', 'AbortError'));

    signal.addEventListener('abort', () => xhr.abort());

    const formData = new FormData();
    formData.append('file', file);
    xhr.send(formData);
  });
}

function useFileUploadQueue() {
  const [uploads, setUploads] = useState<UploadEntry[]>([]);
  const controllers = useRef(new Map<string, AbortController>());

  function updateEntry(id: string, patch: Partial<UploadEntry>) {
    setUploads((prev) => prev.map((u) => (u.id === id ? { ...u, ...patch } : u)));
  }

  async function startUpload(entry: UploadEntry) {
    const controller = new AbortController();
    controllers.current.set(entry.id, controller);
    updateEntry(entry.id, { status: 'uploading', progress: 0 });
    try {
      await uploadWithProgress(entry.file, (pct) => updateEntry(entry.id, { progress: pct }), controller.signal);
      updateEntry(entry.id, { status: 'success', progress: 100 });
    } catch (err: any) {
      if (err.name === 'AbortError') {
        updateEntry(entry.id, { status: 'cancelled' });
      } else {
        updateEntry(entry.id, { status: 'error', error: err.message });
      }
    } finally {
      controllers.current.delete(entry.id);
    }
  }

  function addFiles(files: FileList) {
    const newEntries: UploadEntry[] = Array.from(files).map((file) => {
      const validationError = validateFile(file);
      return {
        id: crypto.randomUUID(),
        file,
        status: validationError ? 'error' : 'queued',
        progress: 0,
        error: validationError ?? undefined,
      };
    });
    setUploads((prev) => [...prev, ...newEntries]);
    newEntries.filter((e) => e.status === 'queued').forEach(startUpload);
  }

  function cancel(id: string) {
    controllers.current.get(id)?.abort();
  }

  function retry(id: string) {
    const entry = uploads.find((u) => u.id === id);
    if (entry) startUpload(entry);
  }

  return { uploads, addFiles, cancel, retry };
}

function FileUploader() {
  const { uploads, addFiles, cancel, retry } = useFileUploadQueue();
  const [isDragOver, setIsDragOver] = useState(false);

  return (
    <div>
      <div
        role="button"
        tabIndex={0}
        aria-label="Upload files, drag and drop or press Enter to browse"
        onDragOver={(e) => { e.preventDefault(); setIsDragOver(true); }}
        onDragLeave={() => setIsDragOver(false)}
        onDrop={(e) => { e.preventDefault(); setIsDragOver(false); addFiles(e.dataTransfer.files); }}
        onClick={() => document.getElementById('file-input')?.click()}
        onKeyDown={(e) => { if (e.key === 'Enter') document.getElementById('file-input')?.click(); }}
        className={'rounded-md border-2 border-dashed p-8 text-center ' + (isDragOver ? 'border-slate-900 bg-slate-50' : 'border-slate-300')}
      >
        Drag files here or click to browse
      </div>
      <input
        id="file-input"
        type="file"
        multiple
        accept={ALLOWED_TYPES.join(',')}
        className="sr-only"
        onChange={(e) => e.target.files && addFiles(e.target.files)}
      />

      <ul className="mt-4 space-y-2">
        {uploads.map((u) => (
          <li key={u.id} className="flex items-center gap-3 rounded border p-2 text-sm">
            <span className="flex-1 truncate">{u.file.name}</span>
            {u.status === 'uploading' && (
              <>
                <div
                  role="progressbar"
                  aria-valuenow={u.progress}
                  aria-valuemin={0}
                  aria-valuemax={100}
                  aria-label={'Uploading ' + u.file.name}
                  className="h-1.5 w-24 overflow-hidden rounded bg-slate-200"
                >
                  <div className="h-full bg-slate-900" style={{ width: u.progress + '%' }} />
                </div>
                <button aria-label={'Cancel upload of ' + u.file.name} onClick={() => cancel(u.id)}>Cancel</button>
              </>
            )}
            {u.status === 'success' && <span className="text-green-600">Uploaded</span>}
            {u.status === 'error' && (
              <>
                <span role="alert" className="text-red-600">{u.error}</span>
                <button onClick={() => retry(u.id)}>Retry</button>
              </>
            )}
            {u.status === 'cancelled' && <span className="text-slate-400">Cancelled</span>}
          </li>
        ))}
      </ul>
    </div>
  );
}

