// Using @dnd-kit/core + @dnd-kit/sortable conceptually (simplified drop-handling logic shown; the library supplies pointer + keyboard sensors, collision detection, and a11y announcements out of the box)

function useBoardState(initial: BoardState) {
  const [board, setBoard] = useState(initial);
  const snapshotRef = useRef<BoardState | null>(null);

  function moveCard(cardId: string, fromColumn: string, toColumn: string, toIndex: number) {
    snapshotRef.current = board; // remember for rollback

    setBoard((prev) => {
      const fromIds = prev.cardsByColumn[fromColumn].filter((id) => id !== cardId);
      const toIds = [...(fromColumn === toColumn ? fromIds : prev.cardsByColumn[toColumn])];
      toIds.splice(toIndex, 0, cardId);
      return {
        ...prev,
        cardsByColumn: {
          ...prev.cardsByColumn,
          [fromColumn]: fromColumn === toColumn ? toIds : fromIds,
          [toColumn]: toIds,
        },
      };
    });

    api.moveTicket(cardId, toColumn, toIndex).catch(() => {
      if (snapshotRef.current) setBoard(snapshotRef.current); // rollback to exact prior state
      toast.error('That move is not allowed for this ticket.');
    });
  }

  // Keyboard-alternative entry point, callable from a card's "Move to..." menu,
  // completely independent of any pointer drag gesture:
  function moveCardViaMenu(cardId: string, toColumn: string) {
    const fromColumn = Object.keys(board.cardsByColumn).find((col) =>
      board.cardsByColumn[col].includes(cardId)
    )!;
    moveCard(cardId, fromColumn, toColumn, board.cardsByColumn[toColumn].length);
  }

  return { board, moveCard, moveCardViaMenu };
}

function DndKitBoard() {
  const { board, moveCard } = useBoardState(initialBoard);

  function handleDragEnd(event: DragEndEvent) {
    const { active, over } = event;
    if (!over) return;
    const cardId = active.id as string;
    const fromColumn = findColumnForCard(board, cardId);
    const toColumn = over.data.current?.columnId ?? findColumnForCard(board, over.id as string);
    const toIndex = over.data.current?.index ?? board.cardsByColumn[toColumn].length;
    if (fromColumn !== toColumn || toIndex !== board.cardsByColumn[fromColumn].indexOf(cardId)) {
      moveCard(cardId, fromColumn, toColumn, toIndex);
    }
  }

  return (
    <DndContext
      sensors={useSensors(useSensor(PointerSensor), useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates }))}
      onDragEnd={handleDragEnd}
    >
      <div className="flex gap-4 overflow-x-auto">
        {board.columns.map((col) => (
          <Column key={col.id} column={col} cardIds={board.cardsByColumn[col.id]} cardsById={board.cardsById} />
        ))}
      </div>
    </DndContext>
  );
}

