referenceSolution:
function QueryStateSwitch<T>({
  isLoading, isError, data, isEmpty, onRetry, skeleton, emptyState, children,
}: QueryStateSwitchProps<T>) {
  if (isLoading) return <div aria-hidden="true">{skeleton}</div>;
  if (isError) {
    return (
      <div role="alert" className="p-4 text-sm">
        <p className="text-red-600">Something went wrong loading this data.</p>
        <button onClick={onRetry} className="mt-2 underline">Retry</button>
      </div>
    );
  }
  if (data === undefined || isEmpty(data)) return <>{emptyState}</>;
  return <>{children(data)}</>;
}

